    experiment: { title: "স্ক্যান সাজান, বাছাই দেখুন", body: "উৎসের বাজেট ও প্রার্থীর দল বদলান। সংকীর্ণ স্ক্যানে গল্প বাদ পড়তে পারে; বিস্তৃত স্ক্যানে একই গল্পে শ্রম যেতে পারে। চারটি ফল সম্পাদকীয় উদাহরণ, গণনা করা পূর্বাভাস নয়।", prompt: "স্ক্যান বাজেট ও প্রার্থীর দল নির্ধারণ করুন", note: "কৃত্রিম দৃশ্য · লাইভ তথ্য নেই · পারফরম্যান্সের পূর্বাভাস নয়।", budgetLabel: "উৎসের স্লট", candidateLabel: "পর্যালোচনার প্রার্থী", budgetChoices: [{ value: 2, label: "২টি স্লট" }, { value: 4, label: "৪টি স্লট" }], candidateChoices: [{ value: 3, label: "৩ জন প্রার্থী" }, { value: 6, label: "৬ জন প্রার্থী" }], outcomes: { "2:3": { title: "মনোযোগী সংক্ষিপ্ত তালিকা", body: "দুটি স্লটে সীমিত স্ক্যান হয়। তিনজন প্রার্থী দেখলে পর্যালোচনা কেন্দ্রীভূত থাকে, তবে কিছু কভারেজ বাদ যায়।" }, "2:6": { title: "প্রার্থী বেশি, বাজেট একই", body: "ছয়জন প্রার্থী দুটি স্লটের জন্য প্রতিযোগিতা করে। নতুন তথ্য তুলনা করুন এবং কী বাদ পড়তে পারে দেখুন।" }, "4:3": { title: "অব্যবহৃত সক্ষমতা", body: "চারটি স্লটে বেশি কভারেজ সম্ভব, কিন্তু দেখা যাচ্ছে মাত্র তিনজন। বাজেট বাড়লেই প্রমাণ বাড়ে না।" }, "4:6": { title: "বিস্তৃত তুলনা", body: "চারটি স্লটে ছয়জনের মধ্যে বেশি কভার করা যায়। বাড়তি কভারেজ নতুন ঘটনা আনে, নাকি পুনরাবৃত্তি—তা দেখুন।" } } },
    limits: ["প্ল্যাটফর্মের মোট কাউন্টার প্রতিটি লাইক বা রিপোস্টের সঠিক সময় জানায় না; ব্যবধানের বৃদ্ধি ঘটনাকাল নয়।", "গাণিতিক ফল বাস্তব গতি, কভারেজ বা বাণিজ্যিক মূল্য প্রমাণ করে না; আলাদা বাস্তবায়ন ও রিপ্লে পরীক্ষা দরকার।", "এই দিকটি রিচ, ভাইরাল হওয়া, নির্ভুলতা বা আগাম সতর্কতার নিশ্চয়তা দেয় না।"],
    closing: { title: "পরের সুবিধা: কী এড়াতে হবে জানা।", body: "Ispatla এমন গবেষণা ডেস্কের সম্ভাবনা খুঁজছে, যা সংকেত ব্যাখ্যা করবে এবং বাছাইয়ের সীমা দেখাবে। ধারণাটি এগোলে প্রমাণই কথা বলবে।", cta: "Ispatla দেখুন" },
